import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        StringTokenizer st = new StringTokenizer(new String(System.in.readAllBytes()));
        int n = Integer.parseInt(st.nextToken()), ans = 0;
        for (int i = 0; i < n; i++) {
            int[] cnt = new int[26];
            for (char ch : st.nextToken().toCharArray()) cnt[ch - 'a']++;
            for (char ch : st.nextToken().toCharArray()) cnt[ch - 'a']--;
            for (int v : cnt) if (v != 0) { ans++; break; }
        }
        System.out.println(ans);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<26)
	sc.Split(bufio.ScanWords)
	next := func() string { sc.Scan(); return sc.Text() }
	n, _ := strconv.Atoi(next())
	ans := 0
	for i := 0; i < n; i++ {
		var cnt [26]int
		for _, ch := range next() {
			cnt[ch-'a']++
		}
		for _, ch := range next() {
			cnt[ch-'a']--
		}
		if cnt != [26]int{} {
			ans++
		}
	}
	fmt.Println(ans)
}
